	if *jh.Seq <= 0 {
		return h, fmt.Errorf("seq 必须是大于 0 的整数, 得到 %d", *jh.Seq)
	}
	h.Seq = *jh.Seq
	if strings.TrimSpace(jh.CollectedAt) == "" {
		return h, fmt.Errorf("collected_at 必须明确提供")
	}
	t, err := time.Parse(time.RFC3339Nano, jh.CollectedAt)
	if err != nil {
		return h, fmt.Errorf("collected_at 必须是带时区的 RFC3339 时间 (如 2026-10-01T12:00:00+08:00): %w", err)
	}
	h.CollectedAt = t
	if strings.TrimSpace(jh.Version) == "" {
		return h, fmt.Errorf("version 不能为空")
	}
	if jh.Height == nil {
		return h, fmt.Errorf("height 必须明确提供")
	}
	if *jh.Height < 0 {
		return h, fmt.Errorf("height 不得为负, 得到 %d", *jh.Height)
	}
	h.Height = *jh.Height
	if jh.Missed == nil {
		return h, fmt.Errorf("missed 必须明确提供")
	}
	if *jh.Missed < 0 {
		return h, fmt.Errorf("missed 不得为负, 得到 %d", *jh.Missed)
	}
	h.Missed = *jh.Missed
	if jh.ReceivedAt != "" {
		rt, err := time.Parse(time.RFC3339Nano, jh.ReceivedAt)
		if err != nil {
			return h, fmt.Errorf("received_at 时间格式无效: %w", err)
		}
		h.ReceivedAt = rt
	}
	return h, nil
}

// Validate checks a heartbeat against the receive time. It never mutates state.
func (h Heartbeat) Validate(receivedAt time.Time) error {
	if strings.TrimSpace(h.NodeID) == "" {
		return fmt.Errorf("node_id 不能为空")
	}
	if h.Seq <= 0 {
		return fmt.Errorf("seq 必须是大于 0 的整数, 得到 %d", h.Seq)
	}
	if h.CollectedAt.IsZero() {
		return fmt.Errorf("collected_at 必须明确提供")
	}
	if h.CollectedAt.Location() == time.UTC {
		// UTC carries a zone too; only a bare offset-less time is rejected,
		// which cannot round-trip through RFC3339 parsing anyway.
	}
	if strings.TrimSpace(h.Version) == "" {
		return fmt.Errorf("version 不能为空")
	}
	if h.Height < 0 {
		return fmt.Errorf("height 不得为负, 得到 %d", h.Height)
	}
	if h.Missed < 0 {
		return fmt.Errorf("missed 不得为负, 得到 %d", h.Missed)
	}
	if h.CollectedAt.After(receivedAt) {
		return fmt.Errorf("collected_at %s 不得晚于接收时间 %s",
			formatTime(h.CollectedAt), formatTime(receivedAt))
	}
	return nil
}

// sameInstant reports whether a and b denote the same absolute instant.
func sameInstant(a, b time.Time) bool {
	return a.Equal(b)
}

// contentEqual implements duplicate identity: same node, same seq and every
// field equal, with collected times compared as instants (zone-independent).
func heartbeatEqual(a, b Heartbeat) bool {
	return a.NodeID == b.NodeID &&
		a.Seq == b.Seq &&
		sameInstant(a.CollectedAt, b.CollectedAt) &&
		a.Version == b.Version &&
		a.Height == b.Height &&
		a.Missed == b.Missed
}

// HealthStatus is the result of a telemetry-backed health query.
type HealthStatus struct {
	NodeID string
	// HasTelemetry is false when the node has no heartbeat; callers must not
	// interpret zero-valued telemetry as healthy.
	HasTelemetry bool
	Online       bool
	Healthy      bool
	// Seq / CollectedAt / Version / Height / Missed describe the record that
	// was actually used (the node's max-seq heartbeat).
	Seq         int64
	CollectedAt time.Time
	Version     string
	Height      int64
	Missed      int64
	// Findings carries abnormal reasons, mirroring Evaluate wording.
	Findings []string
	// Reason is a machine-readable short code for the headline state:
	// "", "no-telemetry", "query-before-telemetry", "offline".
	Reason string
}

const onlineWindow = 60 * time.Second

// QueryHealth derives health from stored telemetry. expectedVersion and
// toleratedMisses reuse the Evaluate rules. queryAt is the query time.
//
// Latest means the greatest seq for the node regardless of arrival time, so a
// freshly back-filled stale record cannot make old telemetry look healthy.
func QueryHealth(latest *Heartbeat, queryAt time.Time, expectedVersion string, toleratedMisses int64) (HealthStatus, error) {
	st := HealthStatus{NodeID: latest.NodeIDOr(""), Healthy: true}
	_ = st
	if latest == nil {
		return HealthStatus{HasTelemetry: false, Healthy: false, Reason: "no-telemetry",
			Findings: []string{"无遥测"}}, nil
	}
	st = HealthStatus{
		NodeID:      latest.NodeID,
		HasTelemetry: true,
		Healthy:     true,
		Seq:         latest.Seq,
		CollectedAt: latest.CollectedAt,
		Version:     latest.Version,
		Height:      latest.Height,
		Missed:      latest.Missed,
	}
	if queryAt.Before(latest.CollectedAt) {
		return HealthStatus{
			NodeID:       latest.NodeID,
			HasTelemetry: true,
			Healthy:      false,
			Seq:          latest.Seq,
			CollectedAt:  latest.CollectedAt,
			Version:      latest.Version,
			Height:       latest.Height,
			Missed:       latest.Missed,
			Reason:       "query-before-telemetry",
			Findings:     []string{"查询时间早于最新采集时间"},
		}, fmt.Errorf("查询时间 %s 早于该节点最新采集时间 %s",
			formatTime(queryAt), formatTime(latest.CollectedAt))
	}
	age := queryAt.Sub(latest.CollectedAt)
	if age <= onlineWindow {
		st.Online = true
	} else {
		st.Online = false
		st.Healthy = false
		st.Reason = "offline"
		st.Findings = append(st.Findings, "offline")
	}
	if latest.Version != expectedVersion {
		st.Healthy = false
		st.Findings = append(st.Findings, "version skew: "+latest.Version+" != "+expectedVersion)
	}
	if latest.Missed > toleratedMisses {
		st.Healthy = false
		st.Findings = append(st.Findings, "missed duties above tolerance")
	}
	return st, nil
}

// NodeIDOr returns the node id or the fallback when h is the zero value.
func (h Heartbeat) NodeIDOr(fallback string) string {
	if h.NodeID == "" {
		return fallback
	}
	return h.NodeID
}

// formatTime renders t with its zone for human and machine output.
func formatTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.Format(time.RFC3339Nano)
}

