// Rule for structural anomalies (bad magic/length/CRC, short read): if the
// damaged frame starts at or after committedEnd it is part of an uncommitted
// batch and is discarded; anything before committedEnd is hard corruption.
func (s *Store) replay(f *os.File) (committedEnd int64, tail bool, err error) {
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return 0, false, err
	}

	var (
		off      int64
		pending  = map[uint64][]Heartbeat{}
		maxBatch uint64
	)

	// dropTail truncates everything from the current frame start.
	dropTail := func() (int64, bool, error) {
		if err := f.Truncate(committedEnd); err != nil {
			return 0, false, err
		}
		return committedEnd, true, nil
	}
	corrupt := func(reason string) error {
		return &CorruptionError{Path: s.logPath(), Offset: off, Reason: reason}
	}
	// anomaly handles an I/O/framing failure at frame start off.
	anomaly := func(reason string) (int64, bool, error) {
		if off >= committedEnd {
			return dropTail()
		}
		return 0, false, corrupt(reason)
	}

	for {
		frameOff := off
		magic := make([]byte, 4)
		n, readErr := io.ReadFull(f, magic)
		if readErr == io.EOF && n == 0 {
			break // clean frame boundary
		}
		if readErr != nil {
			if readErr == io.EOF || readErr == io.ErrUnexpectedEOF {
				return anomaly("帧魔数不完整（疑似未提交的崩溃尾巴）")
			}
			return 0, false, readErr
		}
		if string(magic) != frameMagic {
			return anomaly("帧魔数不匹配")
		}

		header := make([]byte, 5)
		if _, readErr := io.ReadFull(f, header); readErr != nil {
			if readErr == io.EOF || readErr == io.ErrUnexpectedEOF {
				return anomaly("帧头不完整")
			}
			return 0, false, readErr
		}
		typ := header[0]
		length := int(binary.BigEndian.Uint32(header[1:5]))
		if length < 8 || length > maxFramePayload {
			return anomaly(fmt.Sprintf("帧长度异常: %d", length))
		}

		payload := make([]byte, length)
		if _, readErr := io.ReadFull(f, payload); readErr != nil {
			if readErr == io.EOF || readErr == io.ErrUnexpectedEOF {
				return anomaly("帧载荷不完整")
			}
			return 0, false, readErr
		}
		crcBuf := make([]byte, 4)
		if _, readErr := io.ReadFull(f, crcBuf); readErr != nil {
			if readErr == io.EOF || readErr == io.ErrUnexpectedEOF {
				return anomaly("帧校验和不完整")
			}
			return 0, false, readErr
		}

		checked := make([]byte, 0, 5+length)
		checked = append(checked, header...)
		checked = append(checked, payload...)
		if binary.BigEndian.Uint32(crcBuf) != crc32.ChecksumIEEE(checked) {
			return anomaly("CRC 校验失败")
		}

