func resolveAt(at string) (time.Time, error) {
	if at == "" {
		return time.Now(), nil
	}
	t, err := time.Parse(time.RFC3339Nano, at)
	if err != nil {
		return time.Time{}, fmt.Errorf("--at 必须是带时区的 RFC3339 时间 (如 2026-10-01T12:00:00+08:00): %w", err)
	}
	return t, nil
}

