	fmt.Fprintln(os.Stderr, "错误: "+err.Error())
	os.Exit(1)
}

func printJSON(v any) {
	out, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		fail(err)
	}
	os.Stdout.Write(out)
	fmt.Println()
}

